const $=id=>document.getElementById(id);
const supabaseClient=window.supabaseClient;
let produtos=[],categorias=[],pedidos=[],clientes=[],promocoes=[],configLoja=null;
let ingredientesAtual=[],adicionalAtual=[],adicionaisCatalogo=[],tamanhosAtual=[],fotoAtual=null,logoData=null,bannerData=null,comboProdutosAtual=[];
const COMBO_MARKER="__ELSHADDAI_COMBO_V1__";
const MESCLA_MARKER="__ELSHADDAI_MESCLA_V1__";
let pesquisaProdutos="",categoriaFiltro="",statusPedidoFiltro="todos";
const fidKeyMeta="elshaddai_fidelidade_meta",fidKeyBen="elshaddai_fidelidade_beneficio",fidKeyAtivo="elshaddai_fidelidade_ativa";

const moeda=v=>Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const esc=v=>String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));
const arr=v=>Array.isArray(v)?v:[];
function descricaoVisivel(v){return String(v||"").split("\n").filter(l=>!l.startsWith(COMBO_MARKER+"|")&&!l.startsWith(MESCLA_MARKER)).join("\n").trim()}
function extrairMesclavelDescricao(v){return String(v||"").split("\n").some(l=>l.trim()===MESCLA_MARKER)}
function extrairComboDescricao(v){const t=String(v||"");const m=t.match(new RegExp(COMBO_MARKER+"\\|(.*)$"));if(!m)return[];try{const x=JSON.parse(m[1]);return Array.isArray(x?.produtos)?x.produtos.map(String):[]}catch{return[]}}
function descricaoComCombo(texto){const base=String(texto||"").trim();let out=base;if(comboProdutosAtual.length)out+=(out?"\n":"")+COMBO_MARKER+"|"+JSON.stringify({produtos:comboProdutosAtual});if($("produtoMesclavel")?.checked)out+=(out?"\n":"")+MESCLA_MARKER;return out}
function extrasPedido(p){
  try{const x=JSON.parse(p?.observacao||"{}");return x&&typeof x==="object"?x:{}}catch{return {}}
}
function valorLiquidoPedido(p){const x=extrasPedido(p);return Math.max(0,Number(p?.total||0)-Number(x?.reembolso||0));}
function telefoneWhatsApp(v){let n=String(v||"").replace(/\D/g,"");if(n.length===10||n.length===11)n="55"+n;return n;}
function statusTexto(s){return ({novo:"Novo",em_preparo:"Em preparo",pronto:"Pronto",saiu_entrega:"Saiu para entrega",concluido:"Concluído",cancelado:"Pedido negado"}[s]||s||"Novo");}
function dataBR(v){try{return new Date(v).toLocaleString("pt-BR")}catch{return String(v||"")}}

function definirStatus(texto, tipo="ok") {
  const el=$("status");
  if(!el)return;
  el.textContent=texto;
  el.style.background=tipo==="erro"?"#ffe8e8":"#eaf8ee";
  el.style.color=tipo==="erro"?"#a00018":"#237b39";
}

async function testarConexaoSupabase(){
  try{
    if(!window.supabaseClient) throw new Error("Cliente Supabase não carregado.");
    const r=await window.supabaseClient.from("categorias").select("id",{head:true,count:"exact"});
    if(r.error) throw r.error;
    definirStatus("Conectado");
    return true;
  }catch(e){
    console.error("Falha na conexão com Supabase:",e);
    definirStatus("Não conectado","erro");
    return false;
  }
}

async function iniciar(){
  document.querySelectorAll(".nav button").forEach(b=>{b.onclick=()=>abrirTela(b.dataset.screen);});
  const fp=$("fotoProduto"); if(fp)fp.addEventListener("change",e=>lerImagem(e.target,f=>{fotoAtual=f;mostrarImagem("previewFoto",f)}));
  const lf=$("configLogoFile"); if(lf)lf.addEventListener("change",e=>lerImagem(e.target,f=>{logoData=f;mostrarImagem("configLogoPreview",f)}));
  const bf=$("configBannerFile"); if(bf)bf.addEventListener("change",e=>lerImagem(e.target,f=>{bannerData=f;mostrarImagem("configBannerPreview",f)}));
  // A marcação de limpeza antiga não bloqueia mais a abertura do ADM.
  $("manualProduto")?.addEventListener("change",()=>{const p=produtos.find(x=>String(x.id)===String($("manualProduto").value));if(p)$("manualPreco").value=Number(p.preco||0)});
  $("manualFrete")?.addEventListener("input",renderPedidoManualItens);$("manualDesconto")?.addEventListener("input",renderPedidoManualItens);
  await carregarTudoCompleto();
}
function lerImagem(input,cb){const f=input.files?.[0];if(!f)return;if(f.size>1800000){alert("A imagem deve ter no máximo 1,8 MB.");input.value="";return}const r=new FileReader();r.onload=()=>cb(r.result);r.readAsDataURL(f)}
function mostrarImagem(id,src){const i=$(id);if(i&&src){i.src=src;i.style.display="block"}}
function abrirTela(id){document.querySelectorAll(".screen").forEach(s=>s.classList.remove("active"));$(id)?.classList.add("active");document.querySelectorAll(".nav button").forEach(b=>b.classList.toggle("active",b.dataset.screen===id));const tit={inicio:"Início",comprovantes:"Comprovantes",produtos:"Produtos",categorias:"Categorias",configuracao:"Configurações",pedidos:"Pedidos",clientes:"Clientes",dashboard:"Dashboard",promocoes:"Promoções e Cupons",fidelidade:"Fidelidade dos Clientes",whatsapp:"Integração do WhatsApp"};$("tituloTela").textContent=tit[id]||"Início";if(id==="configuracao")carregarConfiguracaoLoja();if(id==="pedidos")carregarPedidos();if(id==="clientes")carregarClientes();if(id==="dashboard")carregarDashboard();if(id==="promocoes")carregarPromocoes();if(id==="fidelidade")carregarFidelidade();if(id==="whatsapp")carregarWhatsApp()}
window.abrirTela=abrirTela;

async function limparProdutosLegadosUmaVez(){
  try{
    const rConf=await supabaseClient.from("configuracoes_loja").select("*").order("id",{ascending:true}).limit(1);
    if(rConf.error)throw rConf.error;
    const c=(rConf.data||[])[0]; if(!c)return;
    const extra=obterConfigExtra(c||{});
    if(extra.dados_teste_zerados_v4)return;
    const info=String(extra.informacoes||"").trim()+"\n"+ELSHADDAI_CONFIG_V3+"|"+JSON.stringify({delivery:extra.delivery||{},fidelidade:extra.fidelidade||null,tempo_aceitar_pedido:extra.tempo_aceitar_pedido||60,mensagem_fidelidade:extra.mensagem_fidelidade||"Olá {nome}, você atingiu sua meta de fidelidade: {beneficio}.",alerta_volume:Number(extra.alerta_volume??100),reset_dashboard_em:extra.reset_dashboard_em||null,dados_teste_zerados_v4:true});
    const u=await supabaseClient.from("configuracoes_loja").update({informacoes:info}).eq("id",c.id);
    if(u.error)throw u.error;
  }catch(e){console.warn("Não foi possível marcar a limpeza inicial:",e)}
}

async function carregarTudoCompleto(){
  definirStatus("Conectando...");
  try{
    if(!window.supabaseClient)throw new Error("Cliente Supabase não carregado.");
    const db=window.supabaseClient;
    const [cats,prods,conf]=await Promise.all([
      db.from("categorias").select("*").order("id"),
      db.from("produtos").select("*").order("id",{ascending:false}),
      db.from("configuracoes_loja").select("*").order("id",{ascending:true}).limit(1)
    ]);
    if(cats.error)throw cats.error;if(prods.error)throw prods.error;if(conf.error)throw conf.error;
    categorias=cats.data||[];produtos=prods.data||[];configLoja=(conf.data||[])[0]||null;
    definirStatus("Conectado");
    try{montarAdicionais();popularCategorias();renderProdutos();renderCategorias();renderComboProdutos($("produtoId")?.value||"");aplicarConfigNosCampos()}catch(e){console.error("Falha ao montar a interface do ADM:",e)}
    atualizarStatusLoja();
    await Promise.allSettled([carregarPedidos(true),carregarClientes(true),carregarDashboard(true),carregarPromocoes(true),carregarFidelidade(true),carregarWhatsApp(true)]);
  }catch(e){
    console.error("Falha ao carregar ADM:",e);definirStatus("Não conectado","erro");
    const ajuda=$("configAjuda");if(ajuda)ajuda.textContent="Falha ao acessar o Supabase: "+(e?.message||"erro desconhecido");
  }
}
function popularCategorias(){const cats=categorias.filter(c=>c.ativo!==false);$("categoriaProduto").innerHTML=cats.map(c=>`<option value="${esc(c.nome)}">${esc(c.nome)}</option>`).join("")||'<option value="">Nenhuma categoria</option>';$("filtroCategoriaProdutos").innerHTML='<option value="">Todas</option>'+cats.map(c=>`<option value="${esc(c.nome)}">${esc(c.nome)}</option>`).join("")}
function montarAdicionais(){const m=new Map();produtos.forEach(p=>arr(p.adicionais).forEach(a=>{if(a?.nome)m.set(a.nome,{nome:a.nome,preco:Number(a.preco||0)})}));adicionaisCatalogo=[...m.values()]}

function novoProduto(){limparFormProduto();$("formTitulo").textContent="Novo produto";$("formProduto").classList.add("open");popularCategorias();renderComboProdutos();}
function editarProduto(id){const p=produtos.find(x=>String(x.id)===String(id));if(!p)return;limparFormProduto();$("formTitulo").textContent="Editar produto";$("produtoId").value=p.id;$("nomeProduto").value=p.nome||"";$("precoProduto").value=p.preco??"";$("categoriaProduto").value=p.categoria||"";$("descricaoProduto").value=descricaoVisivel(p.descricao||"");comboProdutosAtual=extrairComboDescricao(p.descricao||"");$("produtoAtivo").checked=p.ativo!==false;fotoAtual=p.foto||null;mostrarImagem("previewFoto",fotoAtual);tamanhosAtual=arr(p.tamanhos).map(x=>({nome:String(x.nome||""),preco:Number(x.preco||0)}));const temT=$("produtoTemTamanhos"); if(temT)temT.checked=tamanhosAtual.length>0;renderizarTamanhosAdmin();const mes=$("produtoMesclavel");if(mes)mes.checked=extrairMesclavelDescricao(p.descricao||"");ingredientesAtual=arr(p.ingredientes).map(x=>typeof x==="string"?{nome:x,podeRetirar:true}:{nome:x.nome||"",podeRetirar:x.podeRetirar!==false});adicionalAtual=arr(p.adicionais).map(x=>({nome:x.nome,preco:Number(x.preco||0)}));renderIngredientes();renderAdicionais();renderComboProdutos(p.id);$("formProduto").classList.add("open");}
function limparFormProduto(){
  $("produtoId").value="";$("nomeProduto").value="";$("precoProduto").value="";$("descricaoProduto").value="";$("fotoProduto").value="";
  $("produtoAtivo").checked=true;const mes=$("produtoMesclavel");if(mes)mes.checked=false;fotoAtual=null;ingredientesAtual=[];adicionalAtual=[];tamanhosAtual=[];comboProdutosAtual=[];
  const tt=$("produtoTemTamanhos");if(tt)tt.checked=false;const te=$("tamanhosEditor");if(te)te.style.display="none";renderizarTamanhosAdmin();
  $("previewFoto").style.display="none";$("previewFoto").removeAttribute("src");renderIngredientes();renderAdicionais();
}
function renderComboProdutos(excluirId=""){const box=$("comboProdutosLista");if(!box)return;const lista=produtos.filter(p=>String(p.id)!==String(excluirId));box.innerHTML=lista.length?lista.map(p=>`<label><input type="checkbox" value="${esc(p.id)}" ${comboProdutosAtual.includes(String(p.id))?"checked":""} onchange="alternarProdutoCombo('${String(p.id)}',this.checked)"> <span>${esc(p.nome)} — ${moeda(p.preco)}</span></label>`).join(""):"<div class='help'>Nenhum outro produto cadastrado ainda. Crie os produtos primeiro e depois selecione-os no combo.</div>"}
function alternarProdutoCombo(id,ok){id=String(id);if(ok&&!comboProdutosAtual.includes(id))comboProdutosAtual.push(id);if(!ok)comboProdutosAtual=comboProdutosAtual.filter(x=>x!==id)}
function cancelarProduto(){$("formProduto").classList.remove("open")}
function alternarTamanhosProduto(){
  const ativo=$("produtoTemTamanhos")?.checked;
  const editor=$("tamanhosEditor");
  if(editor)editor.style.display=ativo?"block":"none";
  if(ativo && !tamanhosAtual.length) renderizarTamanhosAdmin();
}
function adicionarTamanhoProduto(){
  const nome=$("novoTamanhoNome")?.value.trim();
  const preco=Number($("novoTamanhoPreco")?.value);
  if(!nome||!Number.isFinite(preco)||preco<0)return alert("Informe o nome e o preço do tamanho.");
  if(tamanhosAtual.some(t=>t.nome.toLowerCase()===nome.toLowerCase()))return alert("Esse tamanho já foi adicionado.");
  tamanhosAtual.push({nome,preco});
  $("novoTamanhoNome").value="";$("novoTamanhoPreco").value="";
  const ativo=$("produtoTemTamanhos");if(ativo)ativo.checked=true;
  alternarTamanhosProduto();renderizarTamanhosAdmin();
}
function removerTamanhoProduto(i){tamanhosAtual.splice(i,1);renderizarTamanhosAdmin()}
function renderizarTamanhosAdmin(){
  const lista=$("listaTamanhos");if(!lista)return;
  lista.innerHTML=tamanhosAtual.length?tamanhosAtual.map((t,i)=>`<div class="ingredient-row"><div class="check"><strong>${esc(t.nome)}</strong> — ${moeda(t.preco)}</div><button class="btn danger" type="button" onclick="removerTamanhoProduto(${i})">Remover</button></div>`).join(""):"<div class='help'>Nenhum tamanho cadastrado.</div>";
}

function adicionarIngrediente(){const n=$("novoIngrediente").value.trim();if(!n)return;if(ingredientesAtual.some(x=>x.nome.toLowerCase()===n.toLowerCase()))return alert("Esse ingrediente já foi adicionado.");ingredientesAtual.push({nome:n,podeRetirar:true});$("novoIngrediente").value="";renderIngredientes()}
function removerIngrediente(i){ingredientesAtual.splice(i,1);renderIngredientes()}
function renderIngredientes(){$("ingredientesLista").innerHTML=ingredientesAtual.length?ingredientesAtual.map((x,i)=>`<div class="ingredient-row"><label class="check"><input type="checkbox" ${x.podeRetirar!==false?"checked":""} onchange="ingredientesAtual[${i}].podeRetirar=this.checked"> ${esc(x.nome)}</label><button class="btn danger" onclick="removerIngrediente(${i})">Remover</button></div>`).join(""):"<div class='help'>Nenhum ingrediente cadastrado.</div>"}
function criarAdicional(){const n=$("novoAdicionalNome").value.trim(),p=Number($("novoAdicionalPreco").value);if(!n||!Number.isFinite(p)||p<0)return alert("Informe nome e preço do adicional.");const e=adicionaisCatalogo.find(a=>a.nome.toLowerCase()===n.toLowerCase());if(e)e.preco=p;else adicionaisCatalogo.push({nome:n,preco:p});if(!adicionalAtual.some(a=>a.nome===n))adicionalAtual.push({nome:n,preco:p});$("novoAdicionalNome").value="";$("novoAdicionalPreco").value="";renderAdicionais()}
function renderAdicionais(){$("adicionaisLista").innerHTML=adicionaisCatalogo.map((a,i)=>`<label class="check"><input type="checkbox" ${adicionalAtual.some(x=>x.nome===a.nome)?"checked":""} onchange="alternarAdicional(${i},this.checked)"> ${esc(a.nome)} — ${moeda(a.preco)}</label>`).join("")||"<span class='help'>Nenhum adicional criado.</span>"}
function alternarAdicional(i,ok){const a=adicionaisCatalogo[i];if(ok&&!adicionalAtual.some(x=>x.nome===a.nome))adicionalAtual.push({...a});if(!ok)adicionalAtual=adicionalAtual.filter(x=>x.nome!==a.nome)}
async function salvarProduto(){const nome=$("nomeProduto").value.trim(),preco=Number($("precoProduto").value),categoria=$("categoriaProduto").value;if(!nome||!Number.isFinite(preco)||preco<0||!categoria)return alert("Preencha nome, preço e categoria.");const payload={nome,preco,categoria,descricao:descricaoComCombo($("descricaoProduto").value.trim()),ativo:$("produtoAtivo").checked,disponivel:$("produtoAtivo").checked,foto:fotoAtual||null,ingredientes:ingredientesAtual,adicionais:adicionalAtual,tamanhos:$("produtoTemTamanhos")?.checked?tamanhosAtual:[]};const id=$("produtoId").value;const r=id?await supabaseClient.from("produtos").update(payload).eq("id",id):await supabaseClient.from("produtos").insert(payload);if(r.error)return alert("Não foi possível salvar o produto.\n\n"+r.error.message);cancelarProduto();await carregarTudoCompleto()}
async function excluirProduto(id){if(!confirm("Excluir este produto?"))return;const r=await supabaseClient.from("produtos").delete().eq("id",id);if(r.error)return alert(r.error.message);await carregarTudoCompleto()}
function aplicarPesquisaProdutos(){$("pesquisaProdutos").value;pesquisaProdutos=$("pesquisaProdutos").value.trim().toLowerCase();renderProdutos()}
function aplicarFiltroCategoria(){categoriaFiltro=$("filtroCategoriaProdutos").value;renderProdutos()}
function renderProdutos(){const termo=pesquisaProdutos,box=$("listaProdutos");if(!box)return;const f=produtos.filter(p=>(!categoriaFiltro||p.categoria===categoriaFiltro)&&(!termo||[p.nome,p.categoria,p.descricao].join(" ").toLowerCase().includes(termo)));box.innerHTML=f.length?f.map(p=>`<article class="product">${p.foto?`<img src="${esc(p.foto)}" alt="">`:`<div style="width:78px;height:78px;border-radius:12px;background:#eee;display:grid;place-items:center">Sem foto</div>`}<div><h3>${esc(p.nome)} <span class="badge ${p.ativo!==false?"on":"off"}">${p.ativo!==false?"Ativo":"Inativo"}</span></h3><p>${esc(p.categoria||"Sem categoria")}</p><p>${esc(descricaoVisivel(p.descricao||"")||"Sem descrição")}</p><p class="price">${moeda(p.preco)}</p>${arr(p.tamanhos).length?`<p><strong>Tamanhos:</strong> ${arr(p.tamanhos).map(t=>`${esc(t.nome)} — ${moeda(t.preco)}`).join(" · ")}</p>`:""}</div><div class="actions"><button class="btn light" onclick="editarProduto('${String(p.id)}')">Editar</button><button class="btn danger" onclick="excluirProduto('${String(p.id)}')">Excluir</button></div></article>`).join(""):"<div class='empty'>Nenhum produto encontrado.</div>"}



async function salvarCategoria(){const id=$("categoriaEditId").value,nome=$("nomeCategoria").value.trim(),descricao=$("descricaoCategoria").value.trim(),ativo=$("categoriaAtiva").checked;if(!nome)return alert("Informe o nome da categoria.");const dup=categorias.some(c=>c.nome.toLowerCase()===nome.toLowerCase()&&String(c.id)!==String(id));if(dup)return alert("Essa categoria já existe.");const r=id?await supabaseClient.from("categorias").update({nome,descricao,ativo}).eq("id",id):await supabaseClient.from("categorias").insert({nome,descricao,ativo});if(r.error)return alert(r.error.message);$("categoriaEditId").value="";$("nomeCategoria").value="";$("descricaoCategoria").value="";$("categoriaAtiva").checked=true;await carregarTudoCompleto()}
function editarCategoria(id){const c=categorias.find(x=>String(x.id)===String(id));if(!c)return;$("categoriaEditId").value=c.id;$("nomeCategoria").value=c.nome||"";$("descricaoCategoria").value=c.descricao||"";$("categoriaAtiva").checked=c.ativo!==false;abrirTela("categorias")}
async function excluirCategoria(id){const c=categorias.find(x=>String(x.id)===String(id));if(!c)return;if(produtos.some(p=>p.categoria===c.nome))return alert("Não é possível excluir uma categoria que possui produtos.");if(!confirm("Excluir esta categoria?"))return;const r=await supabaseClient.from("categorias").delete().eq("id",id);if(r.error)return alert(r.error.message);await carregarTudoCompleto()}
function renderCategorias(){$("listaCategorias").innerHTML=categorias.length?categorias.map(c=>`<article class="product"><div></div><div><h3>${esc(c.nome)} <span class="badge ${c.ativo!==false?"on":"off"}">${c.ativo!==false?"Ativa":"Inativa"}</span></h3><p>${esc(c.descricao||"Sem descrição")}</p><p>${produtos.filter(p=>p.categoria===c.nome).length} produto(s)</p><div class="category-tools"><button class="btn light" onclick="verProdutosDaCategoria('${esc(c.nome)}')">Ver produtos</button></div></div><div class="actions"><button class="btn light" onclick="editarCategoria('${c.id}')">Editar</button><button class="btn danger" onclick="excluirCategoria('${c.id}')">Excluir</button></div></article>`).join(""):"<div class='empty'>Nenhuma categoria cadastrada.</div>"}
function verProdutosDaCategoria(nome){categoriaFiltro=nome;pesquisaProdutos="";abrirTela("produtos");const select=$("filtroCategoriaProdutos");if(select)select.value=nome;const busca=$("pesquisaProdutos");if(busca)busca.value="";renderProdutos()}

function atualizarStatusLoja(){const aberta=configLoja?.loja_aberta!==false;const top=$("topLojaStatus"),inicio=$("inicioLojaStatus"),btn=$("btnToggleLoja");[top,inicio].forEach(el=>{if(!el)return;el.textContent=aberta?"Loja aberta":"Loja fechada";el.classList.toggle("open",aberta);el.classList.toggle("closed",!aberta)});if(btn){btn.textContent=aberta?"Fechar loja":"Abrir loja";btn.classList.toggle("store-open",aberta);btn.classList.toggle("store-close",!aberta)}}
function aplicarConfigNosCampos(){
  const c=configLoja;if(!c)return;const extra=obterConfigExtra(c);
  $("configNomeLoja").value=c.nome_loja||"Pastelaria El Shaddai";$("configSlogan").value=c.slogan||"Feito a dois, no ponto pra você!";
  $("configWhatsapp").value=c.whatsapp||"";$("configPix").value=c.pix||"";$("configInformacoes").value=extra.informacoes||"";
  $("configLojaAberta").checked=c.loja_aberta!==false;$("configEntrega").checked=c.entrega_ativa!==false;$("configRetirada").checked=c.retirada_ativa!==false;
  $("configPagamentoPix").checked=c.pagamento_pix!==false;$("configPagamentoCartao").checked=c.pagamento_cartao!==false;$("configPagamentoDinheiro").checked=c.pagamento_dinheiro!==false;
  $("configLogoUrl").value=c.logo&&/^https?:\/\//.test(c.logo)?c.logo:"";$("configBannerUrl").value=c.banner&&/^https?:\/\//.test(c.banner)?c.banner:"";
  logoData=c.logo||null;bannerData=c.banner||null;mostrarImagem("configLogoPreview",logoData);mostrarImagem("configBannerPreview",bannerData);
  aplicarDeliveryNoFormulario(extra.delivery||{});if($("configTempoAceitarPedido"))$("configTempoAceitarPedido").value=String(extra.tempo_aceitar_pedido||60);if($("configVolumeAlerta")){$("configVolumeAlerta").value=String(extra.alerta_volume??100);$("configVolumeAlertaValor").textContent=String(extra.alerta_volume??100)+"%"}aplicarPizzaConfig(extra.pizza||{});aplicarPrinterConfig(extra.printer||{});aplicarIntegracaoConfig(extra.integracao||{});atualizarStatusLoja();
}
