function aplicarDeliveryNoFormulario(delivery={}){
  const d=delivery&&typeof delivery==="object"?delivery:{};
  const modo=d.modo||d.mode||"off";
  const radio=document.querySelector(`input[name="deliveryMode"][value="${modo}"]`);
  document.querySelectorAll('input[name="deliveryMode"]').forEach(x=>x.checked=x===radio);
  if($("deliveryKmMax"))$("deliveryKmMax").value=String(d.km_max??d.kmMax??"");
  if($("deliveryGratisAcima"))$("deliveryGratisAcima").value=String(d.gratis_acima??d.freeAbove??"");
  if($("deliveryTaxaMin"))$("deliveryTaxaMin").value=String(d.taxa_min??d.minFee??"");
  renderBairrosEntrega(d);
  renderKmTabela(d.km_tabela||d.kmTabela||{});
  atualizarModoEntregaAdmin();
}
function renderBairrosEntrega(delivery={}){
  const box=$("bairrosEntregaLista");if(!box)return;
  const atuais=delivery.bairros||{};
  const grupos=[["Maracanaú",BAIRROS_MARACANAU],["Fortaleza",BAIRROS_FORTALEZA]];
  box.innerHTML=grupos.map(([cidade,lista])=>`<div class="bairro-group"><h4 style="grid-column:1/-1;margin:6px 2px;color:#c62828">${esc(cidade)}</h4>${lista.map(nome=>{const chave=cidade+"|"+nome,v=atuais[chave]||atuais[nome]||{};return `<label class="bairro-row"><input type="checkbox" data-bairro="${esc(nome)}" data-cidade="${esc(cidade)}" ${v.ativo===true?"checked":""}><span>${esc(nome)}</span><input type="number" min="0" step="0.01" data-bairro-valor="${esc(chave)}" value="${Number(v.valor||0)}" aria-label="Taxa ${esc(nome)}" placeholder="R$"></label>`}).join("")}</div>`).join("");
}
function atualizarModoEntregaAdmin(){const modo=document.querySelector('input[name="deliveryMode"]:checked')?.value||"off";const bairros=$("bairrosEntregaLista");if(bairros)bairros.style.opacity=modo==="bairro"||modo==="bairro_km"?"1":".75";const km=$("kmTabelaAdmin");if(km)km.style.opacity=modo==="km"||modo==="bairro_km"?"1":".75";}
document.addEventListener("change",e=>{if(e.target?.matches('input[name="deliveryMode"]'))atualizarModoEntregaAdmin()});
function lerConfigExtraDoFormulario(){const bairros={};document.querySelectorAll("#bairrosEntregaLista [data-bairro]").forEach(ch=>{const nome=ch.dataset.bairro,cidade=ch.dataset.cidade||"",chave=cidade?cidade+"|"+nome:nome,inp=Array.from(document.querySelectorAll("[data-bairro-valor]")).find(x=>x.dataset.bairroValor===chave);bairros[chave]={ativo:ch.checked||Number(inp?.value||0)>0,valor:Number(inp?.value||0)}});const km_tabela={};document.querySelectorAll("#kmTabelaAdmin [data-km-faixa]").forEach(row=>{const km=String(row.dataset.kmFaixa),valor=Number(row.querySelector("input")?.value||0);if(Number(km)>0&&valor>=0)km_tabela[km]=valor});return {modo:document.querySelector('input[name="deliveryMode"]:checked')?.value||"off",km_tabela,km_max:Number($("deliveryKmMax").value||0),gratis_acima:Number($("deliveryGratisAcima").value||0),taxa_min:Number($("deliveryTaxaMin").value||0),bairros};}

function renderKmTabela(tabela){const box=$("kmTabelaAdmin");if(!box)return;const entries=Object.entries(tabela||{}).sort((a,b)=>Number(a[0])-Number(b[0]));box.innerHTML=entries.length?entries.map(([km,valor])=>`<div class="km-faixa" data-km-faixa="${esc(km)}"><strong>${esc(km)} km</strong><input type="number" min="0" step="0.01" value="${Number(valor||0)}" aria-label="Valor para ${esc(km)} km"><button class="btn danger" type="button" onclick="this.parentElement.remove()">Excluir</button></div>`).join(""):'<div class="help">Nenhum valor por km cadastrado.</div>'}
function adicionarFaixaKm(){const km=Number($("novoKmDistancia")?.value||0),valor=Number($("novoKmValor")?.value||0);if(km<=0||valor<0)return alert("Informe a distância e o valor.");const box=$("kmTabelaAdmin");if(!box)return;const key=String(km);const old=Array.from(box.querySelectorAll("[data-km-faixa]")).find(x=>x.dataset.kmFaixa===key);if(old)old.querySelector("input").value=valor;else{const row=document.createElement("div");row.className="km-faixa";row.dataset.kmFaixa=key;row.innerHTML=`<strong>${esc(key)} km</strong><input type="number" min="0" step="0.01" value="${valor}"><button class="btn danger" type="button" onclick="this.parentElement.remove()">Excluir</button>`;box.appendChild(row)}$("novoKmDistancia").value="";$("novoKmValor").value=""}
function apagarMidiaLoja(tipo){if(tipo==="logo"){logoData=null;$("configLogoUrl").value="";const i=$("configLogoPreview");if(i){i.removeAttribute("src");i.style.display="none"}}else{bannerData=null;$("configBannerUrl").value="";const i=$("configBannerPreview");if(i){i.removeAttribute("src");i.style.display="none"}}}



function atualizarCamposPromocao(){const tipo=$("promoTipo")?.value||"percentual",titulo=$("promoValorTitulo"),valor=$("promoValor"),campo=$("promoProdutoField");if(titulo)titulo.textContent=tipo==="percentual"?"Desconto (%)":tipo==="valor"?"Desconto em valor":"Valor opcional";if(valor){valor.max=tipo==="percentual"?"100":"";valor.placeholder=tipo==="percentual"?"Ex.: 10":"Ex.: 5,00"}if(campo)campo.style.display=tipo==="produto"?"block":"none"}
function atualizarAjudaRegraPromocao(){const r=$("promoRegraUso")?.value||"livre",el=$("promoRegraAjuda");if(!el)return;const m={livre:"Sem limite: o mesmo cliente pode usar a promoção sempre que cumprir as demais condições.",primeira_compra:"Primeira compra: a promoção só pode ser usada na primeira compra daquele cliente/residência.",uma_vez_por_cliente:"Uma vez por cliente: depois de usar, o mesmo cliente não poderá usar novamente.",a_cada_n:"A cada número de compras: a promoção fica disponível conforme a quantidade de compras definida no campo abaixo."};el.textContent=m[r]||""}function montarProdutosPromocao(){const s=$("promoProduto");if(!s)return;s.innerHTML='<option value="">Selecione um produto</option>'+produtos.filter(p=>p.ativo!==false).map(p=>`<option value="${esc(p.id)}">${esc(p.nome)} — ${moeda(p.preco)}</option>`).join("")}
function promoMeta(p){try{const m=JSON.parse(p.descricao||"");return m&&m.__elshaddai_promo?m:null}catch{return null}}
function textoRegraPromocao(m){const r=m?.regra||"livre";if(r==="primeira_compra")return"Uso: somente na primeira compra da residência/cliente";if(r==="uma_vez_por_cliente")return"Uso: uma vez por residência/cliente";if(r==="a_cada_n")return`Uso: a cada ${Math.max(1,Number(m.compras_necessarias||1))} compra(s)`;return"Uso: sem limite por cliente"}
function textoPromocao(p){const m=promoMeta(p);if(!m)return`${Number(p.desconto||0)}% — ${esc(p.descricao||"")}`;const texto=m.tipo==="percentual"?`${Number(m.valor||0)}% de desconto`:m.tipo==="valor"?`${moeda(m.valor)} de desconto`:`Produto: ${esc(produtos.find(x=>String(x.id)===String(m.produto_id))?.nome||"Produto selecionado")}`;return`${texto}${m.descricao?` — ${esc(m.descricao)}`:""}<br><small>${textoRegraPromocao(m)}</small>`}
async function expirarPromocoesVencidas(lista){const agora=new Date();const expiradas=(lista||[]).filter(p=>p.ativo!==false&&p.validade&&new Date(String(p.validade)+"T23:59:59")<agora);for(const p of expiradas){try{await supabaseClient.from("promocoes").update({ativo:false}).eq("id",p.id);p.ativo=false}catch(e){console.warn("Falha ao desativar promoção expirada",e)}}return lista}
const carregarPromocoesOriginal=carregarPromocoes;
carregarPromocoes=async function(silencioso=false){try{const r=await supabaseClient.from("promocoes").select("*").order("id",{ascending:false});if(r.error)throw r.error;promocoes=await expirarPromocoesVencidas(r.data||[]);montarProdutosPromocao();atualizarCamposPromocao();atualizarAjudaRegraPromocao();renderPromocoes()}catch(e){$("listaPromocoes").innerHTML=`<div class='notice'>Não foi possível carregar as promoções.</div>`;if(!silencioso)console.error(e)}};
renderPromocoes=function(){$("listaPromocoes").innerHTML=promocoes.length?promocoes.map(p=>`<div class="coupon"><span><strong>${esc(p.codigo)}</strong><br>${textoPromocao(p)}<br><small>Validade: ${esc(p.validade||"Sem data")} · ${p.ativo!==false?"Ativa":"Inativa"}</small></span><button class="btn danger" onclick="excluirPromocao('${p.id}')">Excluir</button></div>`).join(""):"<div class='empty'>Nenhuma promoção cadastrada.</div>"};

function imprimirPedido(id){const p=pedidos.find(x=>String(x.id)===String(id));if(!p)return;const x=extrasPedido(p),itens=itensPedido(p),reembolso=Number(x.reembolso||0),liquido=valorLiquidoPedido(p),pr=obterConfigExtra(configLoja||{}).printer||{},vias=Math.max(1,Math.min(3,Number(pr.vias||1)));let box=$("printReceipt");if(!box){box=document.createElement("div");box.id="printReceipt";box.className="print-only";document.body.appendChild(box)}const logo=pr.logo?(configLoja?.logo||"Logo.png"):"";const umaVia=`${logo?`<img src="${esc(logo)}" style="max-width:160px;max-height:70px;display:block;margin:0 auto 8px">`:""}<h1>${esc(pr.titulo||"COMANDA / PEDIDO")}</h1><p><strong>Pedido #${esc(p.id)}</strong></p><p>${esc(dataBR(p.criado_em))}</p><hr><p><strong>Cliente:</strong> ${esc(p.cliente_nome||"")}</p><p><strong>Telefone:</strong> ${esc(p.cliente_telefone||"")}</p><p><strong>Endereço:</strong> ${esc(p.endereco||"")}</p><hr><p><strong>Itens</strong></p><ul>${itens.map(i=>`<li>${esc(i.quantidade||1)}x ${esc(i.nome||i.produto||"")} — ${moeda((i.preco||0)*(i.quantidade||1))}${arr(i.detalhes).length?`<br>${esc(arr(i.detalhes).join(" · "))}`:""}</li>`).join("")}</ul><hr><p>Subtotal: ${moeda(x.subtotal||itens.reduce((s,i)=>s+Number(i.preco||0)*Number(i.quantidade||1),0))}</p><p>Entrega: ${moeda(x.frete||0)}</p><p>Desconto: ${moeda(x.desconto||0)}</p><p>Pagamento: ${esc(p.pagamento||"")}</p>${x.troco?`<p>Troco: ${moeda(x.troco)}</p>`:""}${reembolso?`<p>Estorno: ${moeda(reembolso)}</p>`:""}<p class="total">TOTAL: ${moeda(liquido)}</p>`;box.innerHTML=Array.from({length:vias},(_,i)=>`<div class="print-via">${umaVia}${i<vias-1?"<div style='page-break-after:always'></div>":""}</div>`).join("");setTimeout(()=>window.print(),80)}
function imprimirUltimoPedidoTeste(){const p=pedidos[0];if(!p)return alert("Ainda não há pedido para testar.");imprimirPedido(p.id)}

let novoPedidoAtual=null,novoPedidoTimer=null;let alertaAudioLiberado=false;document.addEventListener("click",()=>{alertaAudioLiberado=true},{once:true});
function tocarAlertaNovoPedido(){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C();if(c.state==="suspended")c.resume();const vol=Math.max(0,Math.min(100,Number($("configVolumeAlerta")?.value??obterConfigExtra(configLoja||{}).alerta_volume??100)))/100;if(vol<=0)return;[0,0.28,0.56,0.84,1.12].forEach(t=>{const o=c.createOscillator(),g=c.createGain();o.frequency.value= t===0.56?980:760;o.type="square";g.gain.setValueAtTime(.0001,c.currentTime+t);g.gain.exponentialRampToValueAtTime(Math.max(.0002,.42*vol),c.currentTime+t+.025);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+t+.22);o.connect(g);g.connect(c.destination);o.start(c.currentTime+t);o.stop(c.currentTime+t+.24)})}catch(e){console.warn("Alerta sonoro indisponível",e)} }
function pedidoEhPago(p){const x=extrasPedido(p);if(x.status_pagamento)return x.status_pagamento==="pago";const pg=String(p.pagamento||"").toLowerCase();return pg.startsWith("pix:")?x.pixPagoAgora===true:pg.startsWith("cartao:")||pg.startsWith("dinheiro")}
function pedidoEhComprovante(p){return p?.status==="concluido"&&pedidoEhPago(p)}
function mostrarNovoPedido(p){novoPedidoAtual=p;const m=$("novoPedidoModal");if(!m)return;const x=extrasPedido(p),it=itensPedido(p),limite=Math.max(15,Number(obterConfigExtra(configLoja||{}).tempo_aceitar_pedido||60));const descTempo=$("novoPedidoModal")?.querySelector(".toolbar p");if(descTempo)descTempo.textContent=`Você tem ${limite} segundo(s) para aceitar este pedido.`;$("novoPedidoConteudo").innerHTML=`<div class="order-box"><strong>Pedido #${esc(p.id)}</strong><br><strong>Cliente:</strong> ${esc(p.cliente_nome||"Não informado")}<br><strong>Telefone:</strong> ${esc(p.cliente_telefone||"Não informado")}<br><strong>Localização:</strong> ${esc(p.endereco||"Retirada na loja")}<br><strong>Modalidade:</strong> ${esc(p.tipo||"")}<br><strong>Itens:</strong><ul class="order-items">${it.map(i=>`<li>${esc(i.quantidade||1)}x ${esc(i.nome||i.produto||"")}${arr(i.detalhes).length?` — ${esc(arr(i.detalhes).join(" · "))}`:""}</li>`).join("")}</ul><strong>Total:</strong> ${moeda(p.total)}${x.bairro?`<br><strong>Bairro:</strong> ${esc(x.bairro)}`:""}</div>`;m.style.display="flex";const bp=$("btnImprimirAlerta");if(bp)bp.style.display=obterConfigExtra(configLoja||{}).printer?.no_alerta?"inline-block":"none";tocarAlertaNovoPedido();let fim=Date.now()+limite*1000;clearInterval(novoPedidoTimer);novoPedidoTimer=setInterval(()=>{const restante=Math.max(0,fim-Date.now());const el=$("novoPedidoTempo");if(el){const seg=Math.ceil(restante/1000);el.textContent=`${String(Math.floor(seg/60)).padStart(2,"0")}:${String(seg%60).padStart(2,"0")}`;}if(!restante){clearInterval(novoPedidoTimer);recusarNovoPedido(true)}},500)}
async function fecharAlertaNovoPedido(){clearInterval(novoPedidoTimer);const m=$("novoPedidoModal");if(m)m.style.display="none";novoPedidoAtual=null}
async function aceitarNovoPedido(){const p=novoPedidoAtual;if(!p)return;const r=await supabaseClient.from("pedidos").update({status:"em_preparo"}).eq("id",p.id);if(r.error)return alert(r.error.message);localStorage.setItem("elshaddai_pedido_avisado_"+p.id,"1");const pr=obterConfigExtra(configLoja||{}).printer||{};await fecharAlertaNovoPedido();await carregarPedidos(true);if(pr.ativo&&pr.ao_aceitar)setTimeout(()=>imprimirPedido(p.id),250)}
function abrirMotivoRecusa(){const p=novoPedidoAtual;if(!p)return;let m=document.getElementById("motivoRecusaModal");if(m)m.remove();m=document.createElement("div");m.id="motivoRecusaModal";m.className="modal-backdrop";m.style.display="flex";m.innerHTML=`<div class="modal-card" style="border:3px solid #c62828;background:#fff8e7"><div class="toolbar"><div><h2 style="color:#c62828;margin:0">Pedido não aceito</h2><p style="margin:5px 0">Informe o motivo que o cliente verá.</p></div></div><textarea id="motivoRecusaTexto" style="width:100%;min-height:120px;padding:12px;border:2px solid #eadcae;border-radius:12px;box-sizing:border-box" placeholder="Ex.: Pedido não aceito por falta de determinado produto."></textarea><div class="actions" style="margin-top:12px"><button class="btn danger" type="button" onclick="confirmarRecusaPedido()">Não aceitar pedido</button><button class="btn light" type="button" onclick="document.getElementById('motivoRecusaModal')?.remove()">Voltar</button></div></div>`;document.body.appendChild(m)}
async function confirmarRecusaPedido(){const p=novoPedidoAtual;if(!p)return;const campo=document.getElementById("motivoRecusaTexto"),motivo=(campo?.value||"").trim();if(!motivo){campo?.focus();return}await finalizarRecusaPedido(motivo)}
async function finalizarRecusaPedido(motivo){const p=novoPedidoAtual;if(!p)return;let meta=extrasPedido(p);meta.pedidoNegado=true;meta.motivoNegacao=motivo;meta.negadoEm=new Date().toISOString();const r=await supabaseClient.from("pedidos").update({status:"cancelado",observacao:JSON.stringify(meta)}).eq("id",p.id);if(r.error){console.error(r.error);return}localStorage.setItem("elshaddai_pedido_avisado_"+p.id,"1");document.getElementById("motivoRecusaModal")?.remove();await fecharAlertaNovoPedido();await carregarPedidos(true)}
async function recusarNovoPedido(auto=false){const p=novoPedidoAtual;if(!p)return;if(auto){await finalizarRecusaPedido("Pedido não aceito porque o tempo para aprovação terminou.");return}abrirMotivoRecusa()}
async function checarNovosPedidos(){const agora=Date.now();const p=(pedidos||[]).find(x=>(x.status||"novo")==="novo"&&!localStorage.getItem("elshaddai_pedido_avisado_"+x.id));if(p&&!novoPedidoAtual)mostrarNovoPedido(p)}
