filtrarComprovantes=function(){const q=normalizarTextoLocal($("buscaComprovante")?.value),dia=$("dataComprovante")?.value||"",mes=$("mesComprovante")?.value||"",ano=$("anoComprovante")?.value||"";const f=pedidos.filter(p=>{if(!pedidoEhComprovante(p))return false;const d=new Date(p.criado_em);if(dia&&new Date(p.criado_em).toISOString().slice(0,10)!==dia)return false;if(mes&&d.getMonth()+1!==Number(mes))return false;if(ano&&d.getFullYear()!==Number(ano))return false;return !q||normalizarTextoLocal([p.id,p.cliente_nome,p.cliente_telefone].join(" ")).includes(q)});const box=$("listaComprovantes");if(!box)return;box.innerHTML=f.length?f.map(p=>`<article class="product" style="cursor:pointer" onclick="abrirComprovante('${p.id}')"><div></div><div><h3>Comprovante do pedido ${esc(p.id)}</h3><p>${esc(p.cliente_nome||"")} · ${esc(p.cliente_telefone||"")}</p><p>${esc(dataBR(p.criado_em))} · Pago · <strong>${moeda(valorLiquidoPedido(p))}</strong></p></div><div class="actions"><button class="btn light" onclick="event.stopPropagation();imprimirPedido('${p.id}')">Imprimir</button><button class="btn light" onclick="event.stopPropagation();compartilharComprovante('${p.id}')">WhatsApp</button></div></article>`).join(""):"<div class='empty'>Nenhum pedido concluído e pago encontrado.</div>"};
