function normalizarTextoLocal(v){return String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim()}
function statusPalavra(s){return ({novo:"NOVO",em_preparo:"PREPARANDO",pronto:"PRONTO",saiu_entrega:"SAIU PARA ENTREGA",concluido:"ENTREGUE",cancelado:"CANCELADO"}[s]||"NOVO")}
function statusClasse(s){return s||"novo"}
function renderInicioPedidosNovo(){const b=$("inicioPedidosLista");if(!b)return;const f=pedidos.slice(0,5);b.innerHTML=f.length?f.map(p=>`<div class="coupon"><span><strong>${esc(p.cliente_nome||"Cliente")}</strong><br><span class="status-word ${statusClasse(p.status||"novo")}">${statusPalavra(p.status||"novo")}</span><br>${esc(dataBR(p.criado_em))}<div class="recent-actions"><button class="btn light" type="button" onclick="imprimirPedido('${p.id}')">Imprimir</button><button class="btn light" type="button" onclick="compartilharComprovante('${p.id}')">WhatsApp</button></div></span><strong>${moeda(p.total)}</strong></div>`).join(""):"<div class='empty'>Nenhum pedido registrado.</div>"}
renderInicioPedidos=renderInicioPedidosNovo;
function compartilharComprovante(id){const p=pedidos.find(x=>String(x.id)===String(id));if(!p)return;const tel=telefoneWhatsApp(p.cliente_telefone);const tracking=new URL("acompanhar.html?id="+encodeURIComponent(p.id),location.href).href;const x=extrasPedido(p)||{};const itens=itensPedido(p).map(i=>`${i.quantidade||1}x ${i.nome||i.produto||""} — ${moeda((i.preco||0)*(i.quantidade||1))}${i.detalhes?.length?" — "+i.detalhes.join(", "):""}`).join("\n");const texto=`*COMPROVANTE*\n*Cliente:* ${p.cliente_nome||""}\n*Telefone:* ${p.cliente_telefone||""}\n*Endereço:* ${p.endereco||""}\n*Itens:*\n${itens}\n*Subtotal:* ${moeda(x.subtotal||0)}\n*Entrega:* ${moeda(x.frete||0)}\n*Desconto:* ${moeda(x.desconto||0)}\n*TOTAL:* ${moeda(valorLiquidoPedido(p))}\n*Pagamento:* ${p.pagamento||""}${x.troco?`\n*Troco:* ${moeda(x.troco)}`:""}${x.reembolso?`\n*Estorno:* ${moeda(x.reembolso)}`:""}\n*ACOMPANHAR PEDIDO:* ${tracking}`;if(tel){const url="https://api.whatsapp.com/send?phone="+tel+"&text="+encodeURIComponent(texto);const w=window.open(url,"_blank");if(!w)location.href=url}else alert("Este pedido não possui telefone para compartilhar o comprovante.")}
function carregarComprovantes(){const anos=new Set();pedidos.forEach(p=>{const d=new Date(p.criado_em);if(!Number.isNaN(d.getTime()))anos.add(d.getFullYear())});const a=$("anoComprovante"),m=$("mesComprovante");if(a){const atual=a.value;a.innerHTML='<option value="">Todos</option>'+Array.from(anos).sort((x,y)=>y-x).map(y=>`<option value="${y}">${y}</option>`).join("");if(atual)a.value=atual}if(m&&!m.dataset.preenchido){m.innerHTML='<option value="">Todos</option>'+Array.from({length:12},(_,i)=>`<option value="${i+1}">${String(i+1).padStart(2,"0")}</option>`).join("");m.dataset.preenchido="1"}filtrarComprovantes()}
function abrirComprovante(id){const p=pedidos.find(x=>String(x.id)===String(id));if(!p)return;const x=extrasPedido(p)||{},itens=itensPedido(p),reembolso=Number(x.reembolso||0),m=$("comprovanteModal");if(!m)return;$("comprovanteModalTitulo").textContent="Comprovante do pedido "+p.id;const obs=x.observacaoLivre||((p.observacao&&!String(p.observacao).trim().startsWith("{"))?p.observacao:"Sem observações");$("comprovanteModalConteudo").innerHTML=`<div class="detail-grid"><div class="detail-box"><strong>Cliente</strong><br>${esc(p.cliente_nome||"Não informado")}</div><div class="detail-box"><strong>Telefone</strong><br>${esc(p.cliente_telefone||"Não informado")}</div><div class="detail-box"><strong>Modalidade</strong><br>${esc(p.tipo||"Não informado")}</div><div class="detail-box"><strong>Endereço</strong><br>${esc(p.endereco||"Não informado")}</div><div class="detail-box"><strong>Pagamento</strong><br>${esc(p.pagamento||"Não informado")}${x.valorRecebido?`<br>Recebido: ${moeda(x.valorRecebido)}`:""}${x.troco?`<br>Troco: ${moeda(x.troco)}`:""}</div><div class="detail-box"><strong>Status</strong><br>${esc(statusTexto(p.status))}</div></div><div class="card" style="margin-top:12px"><h3>Itens do pedido</h3>${itens.length?`<ul class="order-items">${itens.map(i=>`<li>${esc(i.quantidade||1)}x ${esc(i.nome||i.produto||"")} — ${moeda(Number(i.preco||0)*Number(i.quantidade||1))}${arr(i.detalhes).length?`<br><small>${esc(arr(i.detalhes).join(" · "))}</small>`:""}</li>`).join("")}</ul>`:"Nenhum item detalhado."}</div><div class="detail-box"><strong>Observações</strong><br>${esc(obs)}</div><div class="detail-box" style="margin-top:10px"><strong>Valores</strong><br>Subtotal: ${moeda(x.subtotal||itens.reduce((s,i)=>s+Number(i.preco||0)*Number(i.quantidade||1),0))}<br>Entrega: ${moeda(x.frete||0)}<br>Desconto: ${moeda(x.desconto||0)}${reembolso?`<br>Estorno: ${moeda(reembolso)}`:""}<br><strong>Total: ${moeda(valorLiquidoPedido(p))}</strong></div>`;m.style.display="flex"}
