async function carregarFidelidadePorResidencia(silencioso=false){try{if(!configLoja)await carregarConfiguracaoLoja(true);const exF=obterConfigExtra(configLoja||{});if($("fidMensagemWhatsApp"))$("fidMensagemWhatsApp").value=exF.mensagem_fidelidade||"Olá {nome}, você atingiu sua meta de fidelidade: {beneficio}.";const r=await supabaseClient.from("pedidos").select("id,cliente_nome,cliente_telefone,endereco,total,criado_em,observacao").order("id",{ascending:false});if(r.error)throw r.error;const grupos=new Map();(r.data||[]).filter(p=>["em_preparo","pronto","saiu_entrega","concluido"].includes(p.status)&&extrasPedido(p)?.modoTeste!==true&&(!obterConfigExtra(configLoja||{}).reset_fidelidade_em||new Date(p.criado_em)>new Date(obterConfigExtra(configLoja||{}).reset_fidelidade_em))).forEach(p=>{const endereco=normalizarTextoLocal(p.endereco),chave=endereco&&endereco!=="retirada na loja"?endereco:("tel:"+String(p.cliente_telefone||""));if(!grupos.has(chave))grupos.set(chave,{endereco:p.endereco||"",compras:0,total:0,telefones:new Set(),clientes:new Map()});const g=grupos.get(chave);g.compras++;g.total+=Number(p.total||0);if(p.cliente_telefone)g.telefones.add(p.cliente_telefone);const ident=String(p.cliente_telefone||"").replace(/\D/g,"")+"|"+normalizarTextoLocal(p.cliente_nome||"");if(!g.clientes.has(ident))g.clientes.set(ident,{nome:p.cliente_nome||"Cliente",telefone:p.cliente_telefone||""});});const rows=[];grupos.forEach(g=>g.clientes.forEach(c=>rows.push({nome:c.nome,telefone:c.telefone,endereco:g.endereco,telefones:[c.telefone,...g.telefones].filter(Boolean),compras:g.compras,total:g.total})));window.fidelidadeResidencias=rows;renderFidelidadePorResidencia()}catch(e){if(!silencioso)alert(e.message||e)}}
function renderFidelidadePorResidencia(){if(fidelidadeAtiva()){$("fidMeta").value=metaFid();$("fidBeneficio").value=benFid()}else{$("fidMeta").value="";$("fidBeneficio").value=""}const q=normalizarTextoLocal($("pesquisaFidelidade")?.value),m=metaFid(),lista=(window.fidelidadeResidencias||[]).filter(x=>normalizarTextoLocal([x.nome,x.endereco,Array.from(x.telefones).join(" ")].join(" ")).includes(q));$("fidClientes").textContent=lista.length;$("fidCompras").textContent=lista.reduce((s,x)=>s+x.compras,0);if(!fidelidadeAtiva()){$("fidLoyais").textContent="0";$("fidBeneficios").textContent="0";$("listaFidelidade").innerHTML="<div class='empty'>Regra de fidelidade não configurada.</div>";return}$("fidLoyais").textContent=lista.filter(x=>x.compras>=m).length;$("fidBeneficios").textContent=lista.reduce((s,x)=>s+Math.floor(x.compras/m),0);$("listaFidelidade").innerHTML=lista.length?lista.map(x=>{const faltam=x.compras>=m?0:m-(x.compras%m),whats=x.telefone||Array.from(x.telefones).find(Boolean),tpl=String(obterConfigExtra(configLoja||{}).mensagem_fidelidade||"Olá {nome}, você atingiu sua meta de fidelidade: {beneficio}."),msg=encodeURIComponent(tpl.replaceAll("{nome}",x.nome||"Cliente").replaceAll("{beneficio}",benFid()));return `<div class="rank"><span><strong>${esc(x.nome)}</strong><br>${x.compras} compra(s) · ${moeda(x.total)}<br>Endereço: ${esc(x.endereco||"Não informado")}<br>Telefone(s): ${esc(Array.from(x.telefones).filter(Boolean).join(", ")||"Não informado")}<br>${faltam?"Faltam "+faltam+" compra(s)":"Meta atingida — "+esc(benFid())}</span><span>${whats?`<a class="btn light" href="https://wa.me/${telefoneWhatsApp(whats)}?text=${msg}" target="_blank" rel="noopener">WhatsApp</a>`:""}</span></div>`}).join(""):"<div class='empty'>Nenhum cliente/residência encontrado.</div>"}
carregarFidelidade=carregarFidelidadePorResidencia;
async function apagarRegraFidelidade(){if(!configLoja)await carregarConfiguracaoLoja(true);const agora=new Date().toISOString();if(!(await salvarExtraCentral({fidelidade:null,reset_fidelidade_em:agora})))return;localStorage.removeItem(fidKeyMeta);localStorage.removeItem(fidKeyBen);localStorage.removeItem(fidKeyAtivo);$("fidMeta").value="";$("fidBeneficio").value="";await carregarClientes(true);await carregarFidelidadePorResidencia(true)}

async function zerarContagemFidelidade(){if(!configLoja)await carregarConfiguracaoLoja(true);const agora=new Date().toISOString();if(!(await salvarExtraCentral({reset_fidelidade_em:agora})))return;const cr=await supabaseClient.from("clientes").select("id");if(!cr.error)for(const c of cr.data||[])await supabaseClient.from("clientes").update({quantidade_pedidos:0,total_gasto:0}).eq("id",c.id);await carregarClientes(true);await carregarFidelidadePorResidencia(true)}

function zerarDashboardCompleto(){if(!confirm("Zerar todos os contadores do dashboard neste dispositivo? O histórico de pedidos não será apagado."))return;const agora=String(Date.now());["elshaddai_reset_faturamento_dia","elshaddai_reset_faturamento_mes","elshaddai_reset_produtos_vendidos_hoje","elshaddai_reset_dashboard"].forEach(k=>localStorage.setItem(k,agora));carregarDashboard(true);renderProdutosVendidosHoje();alert("Contadores do dashboard zerados.")}
async function definirPagamentoPedido(id,status){if(!["pago","pendente","fiado"].includes(status))return;const p=pedidos.find(x=>String(x.id)===String(id));if(!p)return;const x=extrasPedido(p);x.status_pagamento=status;const r=await supabaseClient.from("pedidos").update({observacao:JSON.stringify(x)}).eq("id",id);if(r.error)return alert("Não foi possível atualizar o pagamento: "+r.error.message);p.observacao=JSON.stringify(x);await carregarPedidos(true);if($("comprovantes")?.classList.contains("active"))carregarComprovantes();alert(status==="fiado"?"Pedido registrado na categoria Fiados.":status==="pago"?"Pagamento marcado como pago.":"Pagamento marcado como pendente.")}
async function executarLimpezaTabela(tabela){
  const escopo=tabela==="pedidos"?"pedidos":tabela==="clientes"?"clientes":"comprovantes";
  const r=await supabaseClient.rpc("reset_operational_data",{p_confirm:"ELSHADDAI-RESET-2026",p_scope:escopo});
  if(r.error){console.error("Limpeza:",r.error);return false}
  return true;
}
async function zerarTodosPedidos(){if(!await executarLimpezaTabela("pedidos"))return;pedidos=[];await Promise.all([carregarPedidos(true),carregarDashboard(true)]);carregarComprovantes()}
async function zerarComprovantes(){if(!await executarLimpezaTabela("comprovantes"))return;await Promise.all([carregarPedidos(true),carregarDashboard(true)]);carregarComprovantes()}
async function zerarClientesSalvos(){if(!await executarLimpezaTabela("clientes"))return;clientes=[];await carregarClientes(true);await carregarDashboard(true)}

